// 从上游固定版本迁移为原生 Vue 组件；保留绘制参数与 CSS，并将派生状态转换为 computed。
import * as UI from "@/lib/types";
import { defineUi, omitProps, domProps, elementRef, jsxTag } from "@/lib/component";
import { createContext, useContext, watchDependencies, stateSetter, initialState, readSlot, renderValue, useExternalStore, useImperativeHandle, useLooseleafDirection, Suspense, lazy as vueLazy, memo as vueMemo, startTransition as vueStartTransition } from "@/lib/composables";
import { Children, cloneElement, createElement, isValidElement } from "@/lib/vnode";
import { cssStyle } from "@/lib/css";
import { computed } from "vue";
import { SidebarBrand } from "@/blocks/sidebar-shared/sidebar-brand";
import { Icon } from "@/components/ui/icon";
import { Sidebar, SidebarContent, SidebarGroup, SidebarHeader, SidebarMenu, SidebarMenuButton, SidebarMenuItem, SidebarRail } from "@/components/ui/sidebar";
const LINKS = [{
  title: "Notes" as const,
  icon: "file-text" as const,
  isActive: true
}, {
  title: "Calendar" as const,
  icon: "calendar" as const
}, {
  title: "Inbox" as const,
  icon: "inbox" as const
}];
export const AppSidebar = defineUi<UI.ComponentProps<typeof Sidebar> & {
  onOpenSettings: (opener: HTMLElement) => void;
}>("AppSidebar", ["onOpenSettings"], (_props, {
  slots: _slots
}) => {
  const onOpenSettings = computed(() => _props["onOpenSettings"]);
  const props = computed(() => omitProps(_props, ["onOpenSettings"]));
  return () => {
    return <Sidebar role="navigation" aria-label="Main" {...domProps(props.value)}>
      <SidebarHeader>
        <SidebarBrand title="Looseleaf Studio" subtitle="Notebook" icon="book-open" />
      </SidebarHeader>
      <SidebarContent>
        <SidebarGroup>
          <SidebarMenu>
            {LINKS.map(item => <SidebarMenuItem key={item.title}>
                <SidebarMenuButton asChild isActive={item.isActive}>
                  <a href={`#${item.title.toLowerCase()}`}>
                    <Icon name={item.icon} />
                    <span>{item.title}</span>
                  </a>
                </SidebarMenuButton>
              </SidebarMenuItem>)}
            <SidebarMenuItem>
              <SidebarMenuButton onClick={event => onOpenSettings.value(event.currentTarget)} aria-haspopup="dialog">
                <Icon name="settings" />
                <span>Settings</span>
              </SidebarMenuButton>
            </SidebarMenuItem>
          </SidebarMenu>
        </SidebarGroup>
      </SidebarContent>
      <SidebarRail />
    </Sidebar>;
  };
});

// 从上游固定版本迁移为原生 Vue 组件；保留绘制参数与 CSS，并将派生状态转换为 computed。
import * as UI from "@/lib/types";
import { defineUi, omitProps, domProps, elementRef, jsxTag } from "@/lib/component";
import { createContext, useContext, watchDependencies, stateSetter, initialState, readSlot, renderValue, useExternalStore, useImperativeHandle, useLooseleafDirection, Suspense, lazy as vueLazy, memo as vueMemo, startTransition as vueStartTransition } from "@/lib/composables";
import { Children, cloneElement, createElement, isValidElement } from "@/lib/vnode";
import { cssStyle } from "@/lib/css";
import { computed, shallowRef, useId } from "vue";
import { settingsSections } from "@/blocks/sidebar-shared/sidebar-data";
import { Breadcrumb, BreadcrumbItem, BreadcrumbLink, BreadcrumbList, BreadcrumbPage, BreadcrumbSeparator } from "@/components/ui/breadcrumb";
import { Dialog, DialogContent, DialogDescription, DialogTitle } from "@/components/ui/dialog";
import { Icon } from "@/components/ui/icon";
import { Label } from "@/components/ui/label";
import { NativeSelect, NativeSelectOption } from "@/components/ui/native-select";
import { Sidebar, SidebarContent, SidebarGroup, SidebarGroupContent, SidebarMenu, SidebarMenuButton, SidebarMenuItem, SidebarProvider } from "@/components/ui/sidebar";
import { Switch } from "@/components/ui/switch";
const initial = () => Object.fromEntries(settingsSections.flatMap(section => section.toggles.map(toggle => [toggle.id, toggle.on])));
export const SettingsDialog = defineUi<{
  open?: boolean;
  onOpenChange?: (open: boolean) => void;
  onCloseAutoFocus?: UI.ComponentProps<typeof DialogContent>["onCloseAutoFocus"];
  defaultSection?: string;
}>("SettingsDialog", ["open", "onOpenChange", "onCloseAutoFocus", "defaultSection"], (_props, {
  slots: _slots
}) => {
  const open = computed(() => _props["open"]);
  const onOpenChange = computed(() => _props["onOpenChange"]);
  const onCloseAutoFocus = computed(() => _props["onCloseAutoFocus"]);
  const defaultSection = computed(() => _props["defaultSection"] === undefined ? "Messages & media" as const : _props["defaultSection"]);
  const section = shallowRef(initialState(defaultSection.value));
  const setSection = stateSetter(section);
  const values = shallowRef<Record<string, boolean>>(initialState(initial));
  const setValues = stateSetter(values);
  const current = computed(() => settingsSections.find(s => s.name === section.value) ?? settingsSections[0]!);
  const selectId = useId();
  return () => {
    return <Dialog open={open.value} onOpenChange={onOpenChange.value}>
      <DialogContent tilt={false} onCloseAutoFocus={onCloseAutoFocus.value} class="max-w-none gap-0 p-0 compact:p-0 calm:p-0 md:max-w-[700px] lg:max-w-[800px]">
        <DialogTitle class="sr-only">Settings</DialogTitle>
        <DialogDescription class="sr-only">Customize your settings here.</DialogDescription>
        <div class="overflow-hidden">
          <SidebarProvider class="min-h-0 items-start">
            <Sidebar collapsible="none" role="navigation" aria-label="Settings sections" class="hidden h-auto self-stretch md:flex">
              <SidebarContent>
                <SidebarGroup>
                  <SidebarGroupContent>
                    <SidebarMenu>
                      {settingsSections.map(item => <SidebarMenuItem key={item.name}>
                          <SidebarMenuButton isActive={item.name === section.value} aria-current={item.name === section.value ? "true" as const : undefined} onClick={() => setSection(item.name)}>
                            <Icon name={item.icon} />
                            <span class="truncate">{item.name}</span>
                          </SidebarMenuButton>
                        </SidebarMenuItem>)}
                    </SidebarMenu>
                  </SidebarGroupContent>
                </SidebarGroup>
              </SidebarContent>
            </Sidebar>
            <div class="flex h-[480px] max-h-[calc(100svh-4rem)] min-w-0 flex-1 flex-col overflow-hidden">
              <header class="flex h-16 shrink-0 items-center gap-2 px-4">
                <Breadcrumb>
                  <BreadcrumbList>
                    <BreadcrumbItem class="hidden md:block">
                      <BreadcrumbLink href="#settings">Settings</BreadcrumbLink>
                    </BreadcrumbItem>
                    <BreadcrumbSeparator class="hidden md:block" />
                    <BreadcrumbItem>
                      <BreadcrumbPage>{current.value.name}</BreadcrumbPage>
                    </BreadcrumbItem>
                  </BreadcrumbList>
                </Breadcrumb>
              </header>
              <div class="flex flex-1 flex-col gap-4 overflow-y-auto p-4 pt-0">
                <div class="grid gap-1.5 md:hidden">
                  <Label for={selectId}>Section</Label>
                  <NativeSelect id={selectId} value={section.value} onChange={event => setSection(event.target.value)} class="w-full">
                    {settingsSections.map(item => <NativeSelectOption key={item.name} value={item.name}>
                        {item.name}
                      </NativeSelectOption>)}
                  </NativeSelect>
                </div>
                <h2 class="font-script text-2xl leading-tight font-semibold">{current.value.name}</h2>
                <p class="-mt-2 text-sm text-muted-foreground">{current.value.intro}</p>
                <ul class="max-w-xl">
                  {current.value.toggles.map(toggle => <li key={toggle.id} class="flex items-start justify-between gap-4 border-b border-pencil-mark/40 py-3 last:border-b-0">
                      <div class="grid gap-1">
                        <Label for={toggle.id}>{toggle.label}</Label>
                        <p id={`${toggle.id}-hint`} class="text-sm text-muted-foreground">
                          {toggle.hint}
                        </p>
                      </div>
                      <Switch id={toggle.id} aria-describedby={`${toggle.id}-hint`} checked={values.value[toggle.id] ?? false} onCheckedChange={checked => setValues(prev => ({
                      ...prev,
                      [toggle.id]: checked
                    }))} />
                    </li>)}
                </ul>
              </div>
            </div>
          </SidebarProvider>
        </div>
      </DialogContent>
    </Dialog>;
  };
});

// 从上游固定版本迁移为原生 Vue 组件；保留绘制参数与 CSS，并将派生状态转换为 computed。
import * as UI from "@/lib/types";
import { defineUi, omitProps, domProps, elementRef, jsxTag } from "@/lib/component";
import { createContext, useContext, watchDependencies, stateSetter, initialState, readSlot, renderValue, useExternalStore, useImperativeHandle, useLooseleafDirection, Suspense, lazy as vueLazy, memo as vueMemo, startTransition as vueStartTransition } from "@/lib/composables";
import { Children, cloneElement, createElement, isValidElement } from "@/lib/vnode";
import { cssStyle } from "@/lib/css";
import { computed, shallowRef } from "vue";
import { AppSidebar } from "@/blocks/sidebar-13/components/sidebar-13-app-sidebar";
import { SettingsDialog } from "@/blocks/sidebar-13/components/sidebar-13-settings-dialog";
import { containedClasses } from "@/blocks/sidebar-shared/sidebar-contained";
import { PageBody, PageHeader, PageNote, PageSheet } from "@/blocks/sidebar-shared/sidebar-page";
import { Button } from "@/components/ui/button";
import { Icon } from "@/components/ui/icon";
import { SidebarProvider } from "@/components/ui/sidebar";
import { cn } from "@/lib/utils";
const Page = defineUi<{
  contained?: boolean;
}>("Page", ["contained"], (_props, {
  slots: _slots
}) => {
  const contained = computed(() => _props["contained"] === undefined ? false : _props["contained"]);
  const c = computed(() => containedClasses(contained.value));
  const open = shallowRef(initialState(false));
  const setOpen = stateSetter(open);
  const opener = shallowRef<HTMLElement | null | null>(null);
  const openSettings = computed(() => (from: HTMLElement) => {
    opener.value = from;
    setOpen(true);
  });
  return () => {
    return <SidebarProvider class={cn("overflow-x-clip", c.value.provider)}>
      <AppSidebar class={c.value.sidebar} onOpenSettings={openSettings.value} />
      <PageSheet class={c.value.inset}>
        <PageHeader crumbs={["Notes", "Untitled"]} bordered>
          <Button variant="outline" size="sm" aria-haspopup="dialog" onClick={event => openSettings.value(event.currentTarget)}>
            <Icon name="settings" />
            Settings
          </Button>
        </PageHeader>
        <PageBody title="Untitled" kicker="Notes">
          <PageNote title="Settings live in a drawer of their own" pose="point">
            Open them from the pad or from the button in the corner. Everything you change is kept while you write.
          </PageNote>
        </PageBody>
      </PageSheet>
      <SettingsDialog open={open.value} onOpenChange={setOpen} onCloseAutoFocus={event => {
        event.preventDefault();
        opener.value?.focus();
      }} />
    </SidebarProvider>;
  };
});
export default Page;
